(2)如果用厚度 $l=1.0\\times10^{-2}\\,\\mathrm{mm}$ ，折射率 $n {=}1.58$ 的透明薄膜复盖在图中的 $S_{1}$ 缝后面，求上述第五级明条纹的坐标 $x^{\\prime},$ 。', '[]'::jsonb, '$x=6.0\\,\\mathrm{mm}$; $x''=-3.6\\,\\mathrm{cm}$', '[]'::jsonb, NULL, NULL, NULL, '（1）$x=kD\\lambda/d=5\\times1.2\\times500\\times10^{-9}/(0.5\\times10^{-3})=6.0\\times10^{-3}\\,\\mathrm{m}=6.0\\,\\mathrm{mm}$。（2）覆盖薄膜产生附加光程差 $\\Delta=(n-1)l=0.58\\times10^{-2}\\,\\mathrm{mm}=5.8\\,\\mathrm{\\mu m}=11.6\\lambda$。第五级明纹位置 $x''=x-(D/d)\\Delta\\approx-3.6\\,\\mathrm{cm}$。', NULL, NULL, '/physics/q075.jpg', 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
