INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-011', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 0, '第 11 题', '在如图所示的单缝的夫琅禾费衍射实验中，将单缝 K 沿垂直于光的入射方向(沿图中的x方向)稍微平移，则', '["衍射条纹移动，条纹宽度不变","衍射条纹移动，条纹宽度变动","衍射条纹中心不动，条纹变宽","衍射条纹不动，条纹宽度不变"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/q054.jpg', 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-012', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 0, '第 12 题', '( xz1000A000009402 ) 波长 $\\lambda=500 \\mathrm{nm}\\big( \\mathrm{nm}=10^{-9}\\mathrm{m}\\big )$ 的单色垂直照射到宽度a=0.25mm 的单缝上，单缝后面放置一凸透镜，在凸透镜的焦平面上放置一屏幕，用以观测衍射条纹。今测得屏幕上中央明条纹一侧第三个暗条纹和另一侧第三个暗条纹之间的距离为 d=12mm，则凸透镜的焦距 f 为', '["2m","1m","0.5m","0.2m"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-013', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 0, '第 13 题', '测量单色光的波长时，下列方法中哪一种方法最为准确？', '["双缝干涉","牛顿环","单缝衍射","光栅衍射"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-014', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 0, '第 14 题', '在双缝干涉实验中，两条缝的宽度原来是相等的。若其中一缝的宽度略变窄(缝中心位置不变)，则', '["干涉条纹的间距变宽","干涉条纹的间距变窄","干涉条纹的间距不变，但原极小处的强度不再为零","不再发生干涉现象"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-015', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 2, '第 15 题', '空气中一玻璃劈形膜其一端厚度为零另一端厚度为0.005cm，折射率为 1.5。现用波长为 $60 0 \\mathrm{nm}\\left( 1 \\mathrm{nm}=10^{-9}\\mathrm{m}\\right)$ 的单色平行光，沿入射角为 $30^{\\circ}$ 角的方向射到劈的上表面，则在劈形膜上形成的干涉条纹数目为', '[]'::jsonb, '$236$', '[]'::jsonb, NULL, NULL, NULL, '斜入射时，光程差为 $2e\\sqrt{n^2-\\sin^2 i}$。条纹数 $N=\\dfrac{2e\\sqrt{n^2-\\sin^2 i}}{\\lambda}=\\dfrac{2\\times 0.005\\times 10^{-2}\\times\\sqrt{1.5^2-\\sin^2 30^{\\circ}}}{600\\times 10^{-9}}\\approx 235.7$，取整为 $236$ 条。', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-016', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 2, '第 16 题', '如图，在双缝干涉实验中，若把一厚度为 e、折射率为 n的薄云母片覆盖在 $S_{1}$ 缝上，中央明条纹将向移动；覆盖云母片后，两束相干光至原中央明纹O处的光程差为。', '[]'::jsonb, '上（$S_1$ 一侧）; $(n-1)e$', '[]'::jsonb, NULL, NULL, NULL, '覆盖 $S_1$ 使该路光程增加 $(n-1)e$，中央条纹向光程较大的 $S_1$ 方向（上）移动；原中央处光程差即为 $(n-1)e$。', NULL, NULL, '/physics/q059.jpg', 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-017', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 2, '第 17 题', '平行单色光垂直入射在缝宽为 $a {=}0.15 \\mathrm{mm}$ 的单缝上。缝后有焦距为 $f=400\\,\\mathrm{mm}$ 的凸透镜，在其焦平面上放置观察屏幕。现测得屏幕上中央明条纹两侧的两个第三级暗纹之间的距离为 8mm，则入射光的波长为=', '[]'::jsonb, '$500\\,\\mathrm{nm}$', '[]'::jsonb, NULL, NULL, NULL, '第三级暗纹位置 $x_3=\\pm3\\lambda f/a$，两侧间距 $6\\lambda f/a=8\\,\\mathrm{mm}$，解得 $\\lambda=8\\times10^{-3}\\times0.15\\times10^{-3}/(6\\times0.4)=500\\times10^{-9}\\,\\mathrm{m}=500\\,\\mathrm{nm}$。', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-018', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 2, '第 18 题', '如图所示的杨氏双缝干涉装置，若用单色自然光照射狭缝S，在屏幕上能看到干涉条纹。若在双缝 $S_{1}$ 和 $S_{2}$ 的一侧分别加一同质同厚的偏振片 $P_{1}, \\ P_{2}$ ，则当 $P_{1}$ 与 $P_{1}$ 的偏振化方向相互时，在屏幕上仍能看到很清晰的干涉条纹。', '[]'::jsonb, '平行', '[]'::jsonb, NULL, NULL, NULL, '两束相干光必须振动方向相同才能产生清晰干涉，因此两偏振片偏振化方向需平行。', NULL, NULL, '/physics/q061.jpg', 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-019', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 2, '第 19 题', '一束平行的自然光，以 $60^{\\circ}$ 角入射到平玻璃表面上．若反射光束是完全偏振的，则透射光束的折射角是 ； 玻璃的折射率为。', '[]'::jsonb, '$30^\\circ$; $\\sqrt{3}$', '[]'::jsonb, NULL, NULL, NULL, '布儒斯特角满足 $\\tan i_B=n$，$i_B=60^\\circ$，$n=\\sqrt{3}$；折射角 $r=90^\\circ-i_B=30^\\circ$。', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-020', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 2, '第 20 题', '若对应于衍射角 $\\varphi=30^{\\circ}$ ，单缝处的波面可划分为 4 个半波带，则单缝的宽度a= λ(λ为入射光波长)。', '[]'::jsonb, '$4$', '[]'::jsonb, NULL, NULL, NULL, '$a\\sin\\phi=4\\cdot\\lambda/2=2\\lambda$，$\\sin30^\\circ=1/2$，故 $a=4\\lambda$。', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-021', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 2, '第 21 题', '一束单色光垂直入射在光栅上，衍射光谱中共出现 5 条明纹。若已知此光栅缝宽度与不透明部分宽度相等，那么在中央明纹一侧的两条明纹分别是级和第级谱线。', '[]'::jsonb, '$1$; $3$', '[]'::jsonb, NULL, NULL, NULL, '$a=b$ 时 $d=2a$，缺级发生在 $k=\\pm2,\\pm4,\\ldots$。可见 $k=0,\\pm1,\\pm3$ 共 5 条，故一侧为 $1$、$3$ 级。', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-022', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 2, '第 22 题', 'He－Ne 激光器发出 $\\lambda=632.8\\,\\mathrm{nm}\\left( \\mathrm{nm}=10^{-9}\\mathrm{m}\\right)$ 的平行光束，垂直照射到一单缝上，在距单缝 3m远的屏上观察夫琅禾费衍射图样，测得两个第二级暗纹间的距离是10cm，则单缝的宽度 $a {=}$ 。', '[]'::jsonb, '$7.6\\times10^{-5}\\,\\mathrm{m}$', '[]'::jsonb, NULL, NULL, NULL, '第二级暗纹间距 $4\\lambda L/a=0.10\\,\\mathrm{m}$，$a=4\\lambda L/0.10=4\\times632.8\\times10^{-9}\\times3/0.10\\approx7.6\\times10^{-5}\\,\\mathrm{m}$。', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-023', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 2, '第 23 题', '在单缝夫琅禾费衍射实验中，设第一级暗纹的衍射角很小，若钠黄光 $( \\left( \\lambda_{1}\\approx 58 9 \\mathrm{mm}\\right)$ 中央明纹宽度为 4.0mm，则 $\\lambda_{2}=44 2 \\mathrm{nm}\\big( 1 \\mathrm{nm}=10^{-9}\\mathrm{m}\\big )$ 的蓝紫色光的中央明纹宽度为。', '[]'::jsonb, '$3.0\\,\\mathrm{mm}$', '[]'::jsonb, NULL, NULL, NULL, '中央明纹宽度 $\\Delta x=2\\lambda f/a$ 与波长成正比，$\\Delta x_2=4.0\\times442/589\\approx3.0\\,\\mathrm{mm}$。', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-024', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 2, '第 24 题', '可见光的波长范围是 400nm─760nm。用平行的白光垂直入射在平面透射光栅上时，它产生的不与另一级光谱重叠的完整的可见光光谱是第级光谱。 $\\left( 1 \\mathrm{nm}=10^{-9}\\mathrm{m}\\right)$', '[]'::jsonb, '$1$', '[]'::jsonb, NULL, NULL, NULL, '$d\\sin\\theta=k\\lambda$。第 $k$ 级最长波长 $760k$ 需小于第 $k+1$ 级最短波长 $400(k+1)$，即 $760k<400(k+1)$，$k<1.05$，故只有 $k=1$ 级完整不重叠。', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-025', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 4, '第 25 题', '在牛顿环装置的平凸透镜和平玻璃板之间充满折射率n=1.33 的透明液体(设平凸透镜和平板玻璃的折射率都大于 1.33)。凸透镜的曲率半径为300cm， 波长 $\\lambda=65 0 \\mathrm{nm}\\big( \\mathrm{nm}=10^{-9}\\mathrm{m}\\big )$ 的平行单色垂直照射到牛顿环装置上，凸透镜顶部刚好与平玻璃板接触，求：
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-026', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 4, '第 26 题', '一束自然光自水中入射到空气界面上，若水的折射率为1.33，空气的折射率为1.00，求布儒斯特角。', '[]'::jsonb, '$i_B=\\arctan\\frac{1.00}{1.33}\\approx36.9^\\circ$', '[]'::jsonb, NULL, NULL, NULL, '光从水中射向空气，布儒斯特角满足 $\\tan i_B=n_2/n_1=1.00/1.33$，$i_B\\approx36.9^\\circ$。', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-027', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 4, '第 27 题', '由强度为 $I_{a}$ 的自然光和强度为 $I_{b}$ 的线偏振光混合而成的一束入射光，垂直入射在一偏振片上，当以入射光方向为转轴旋转偏振片时，出射光将出现最大值和最小值。其比值为 n。试求出 $I_{a}/I_{b}$ 与n的关系。', '[]'::jsonb, '$\\frac{I_a}{I_b}=\\frac{2(n-1)}{1}$', '[]'::jsonb, NULL, NULL, NULL, '透过偏振片后，自然光强度为 $I_a/2$，线偏振光强度为 $I_b\\cos^2\\theta$。最大 $I_{max}=I_a/2+I_b$，最小 $I_{min}=I_a/2$。由 $I_{max}/I_{min}=n$ 得 $(I_a/2+I_b)/(I_a/2)=n$，解得 $I_a/I_b=2/(n-1)$。', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-028', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 4, '第 28 题', '波长范围在 450\\~650nm 之间的复色平行光垂直照射在每厘米有 5000 条刻线的光栅上，屏幕放在透镜的焦面处，屏上第二级光谱各色光在屏上所占范围的宽度为 35.1cm。求透镜的焦距 $f_{\\circ}$ ( $\\mathrm{\\Omega_{1nm=10}-}^{9}\\mathrm{m}\\mathrm{)}$ )', '[]'::jsonb, '$f\\approx1.00\\,\\mathrm{m}$', '[]'::jsonb, NULL, NULL, NULL, '光栅常数 $d=1\\,\\mathrm{cm}/5000=2\\times10^{-6}\\,\\mathrm{m}$。第二级 $\\sin\\theta=k\\lambda/d$。对 $450\\,\\mathrm{nm}$ 和 $650\\,\\mathrm{nm}$ 分别得 $\\theta_1\\approx26.7^\\circ$，$\\theta_2\\approx40.5^\\circ$。屏上宽度 $\\Delta x=f(\\tan\\theta_2-\\tan\\theta_1)=0.351\\,\\mathrm{m}$，解得 $f\\approx1.00\\,\\mathrm{m}$。', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-029', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 4, '第 29 题', '一束平行光垂直入射到某个光栅上，该光束有两种波长的光， $\\lambda_{1}=44 0 \\mathrm{nm}$ ， $\\lambda_{2}=66 0 \\mathrm{nm}\\big( 1 \\mathrm{nm}=10^{-9}\\mathrm{m}\\big )$ 。实验发现，两种波长的谱线(不计中央明纹)第二次重合于衍射角 $\\varphi=60^{\\circ}$ 的方向上。求此光栅的光栅常数 $d_{\\circ}$ 。', '[]'::jsonb, '$d=3.05\\times10^{-6}\\,\\mathrm{m}$', '[]'::jsonb, NULL, NULL, NULL, '重合时 $k_1\\lambda_1=k_2\\lambda_2$，$k_1/k_2=660/440=3/2$。第二次重合取 $k_1=6$，$k_2=4$。由 $d\\sin60^\\circ=k_1\\lambda_1$ 得 $d=6\\times440\\times10^{-9}/\\sin60^\\circ\\approx3.05\\times10^{-6}\\,\\mathrm{m}$。', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-030', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 4, '第 30 题', '氦放电管发出的光垂直照射到某光栅上，测得波长$\\lambda_{1}=0.66 8 \\mu m$ 的谱线的衍射角为 $\\varphi=20^{\\circ}$ 。如果在同样 $\\varphi$ 角处出现波长 $\\lambda_{2}=0.44 7 \\mu m$ 的更高级次的谱线，那么光栅常数最小是多少？', '[]'::jsonb, '$d_{min}\\approx3.92\\,\\mathrm{\\mu m}$', '[]'::jsonb, NULL, NULL, NULL, '$d\\sin\\phi=k_1\\lambda_1=k_2\\lambda_2$，$k_1/k_2=\\lambda_2/\\lambda_1\\approx0.669$。取 $k_1=2$，$k_2=3$ 为最小整数解。$d=2\\lambda_1/\\sin20^\\circ\\approx3.92\\,\\mathrm{\\mu m}$。', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-031', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 4, '第 31 题', '在双缝干涉实验中，单色光源 $S_{0}$ 到两缝 $S_{1}$ 和 $S_{2}$ 的距离分别为 $l_{1}$ 和 $l_{2}$ ，并且 $l_{2}-l_{1}=3\\lambda$ ，λ为入射光的波长，双缝之间的距离为 $d$ ，双缝到屏幕的距离为 $D\\,(D\\gg d)$ ，如图。求：
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-032', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 4, '第 32 题', '双缝干涉实验装置如图所示，双缝与屏之间的距离 $D=120\\,\\mathrm{cm}$ ，两缝之间的距离 d=0.50mm，用波长 $\\lambda=50 0 \\mathrm{nm}\\big( \\mathrm{nm}=10^{-9}\\mathrm{m}\\big )$ 的单色光垂直照射双缝。
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-033', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 4, '第 33 题', '折射率为 1.60 的两块标准平面玻璃板之间形成一个劈形膜(劈尖角 θ 很小)。用波长 $\\lambda=60 0 \\mathrm{nm}\\big( \\mathrm{nm}=10^{-9}\\mathrm{m}\\big )$ 的单色光垂直入射，产生等厚干涉条纹。假如在劈形膜内充满 n=1.40 的液体时的相邻明纹间距比劈形膜内空气时的间距缩小 $\\Delta l=0.5 \\mathrm{mm}$ ，那么劈尖角θ应是多少？', '[]'::jsonb, '$\\theta\\approx1.7\\times10^{-4}\\,\\mathrm{rad}$', '[]'::jsonb, NULL, NULL, NULL, '明纹间距 $l=\\lambda/(2n\\theta)$。空气时 $l_0=\\lambda/(2\\theta)$，液体时 $l=\\lambda/(2n\\theta)$。$\\Delta l=l_0-l=\\frac{\\lambda}{2\\theta}(1-\\frac{1}{n})$。解得 $\\theta=\\frac{\\lambda}{2\\Delta l}(1-\\frac{1}{n})=\\frac{600\\times10^{-9}}{2\\times0.5\\times10^{-3}}\\times\\frac{0.4}{1.4}\\approx1.7\\times10^{-4}\\,\\mathrm{rad}$。', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;